  const readFile3 = deps?.readFile ?? ((p) => fsReadFile3(p, "utf8"));
  const createClient6 = deps?.createClient ?? createOctokitClient;
  const createModel = deps?.createModel ?? defaultCreateModel;
  const log = deps?.log ?? ((msg) => process.stdout.write(msg + "\n"));
